SET @prov_c='%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_death_hosp298 (
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  splevel varchar(2) DEFAULT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	code298 varchar(7) DEFAULT NULL,
	result int(10) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year,code298),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year),
	KEY (code298)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;
DELETE FROM s_death_hosp298  WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_death_hosp298  
(
SELECT
@id,HOSPCODE,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode,cmi.splevel
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,IFNULL(code298,'0')
,COUNT(1) 
FROM
t_death_hosp  s INNER JOIN chospital h ON h.hoscode=s.HOSPCODE
INNER JOIN (SELECT hcode,chwcode,splevel FROM ccmihosp WHERE byear in(@b_year+543) GROUP BY hcode) cmi ON cmi.hcode=s.HOSPCODE
WHERE h.hdc_regist=1 AND h.provcode in(@prov_c) AND cmi.chwcode in(@prov_c)  
GROUP BY s.HOSPCODE,s.code298
);
